    preds = {r['customer_id']: r for r in csv.DictReader(open(pred_path))}
    labs = list(csv.DictReader(open(label_path)))
    cls = collections.defaultdict(lambda: [0,0,0,0])  # tot, correct_dec, correct_uid, wrong
    tp=fp=fn=0; uid_ok=0
    errors=[]
    for l in labs:
        p = preds.get(l['customer_id'])
        pd = p['decision'] if p else 'NO_MATCH'
        pu = (p['matched_uid'] or '') if p else ''
        c = cls[l['class']]
        c[0]+=1
        exp = l['expected_decision']
        if exp=='MATCH':
            if pd=='MATCH':
                tp+=1; c[1]+=1
                if pu==l['expected_uid']: uid_ok+=1; c[2]+=1
                else: errors.append(('WRONGUID',l,pu))
            else:
                fn+=1; errors.append(('FN',l,pu))
        else:
            if pd=='MATCH':
                fp+=1; c[3]+=1; errors.append(('FP',l,pu))
            else:
                c[1]+=1
    rec = tp/(tp+fn) if tp+fn else 1.0
    prec = tp/(tp+fp) if tp+fp else 1.0
    print('recall %.4f  precision %.4f  uid %.4f   (tp=%d fn=%d fp=%d)'%(
        rec, prec, uid_ok/max(1,tp), tp, fn, fp))
    print('%-28s %5s %6s %6s'%('class','n','recall/fpr','uid'))
    bad=[]
    for k in sorted(cls):
        tot, cd, cu, w = cls[k]
        if k.startswith('T'):
            r = cd/tot
            print('%-28s %5d  rec %.3f  uid %.3f'%(k,tot,r,cu/max(1,cd)))
            if r < 0.90: bad.append(k)
        else:
            f = w/tot
            print('%-28s %5d  fpr %.3f'%(k,tot,f))
            lim = 0.01 if k.startswith('R') else 0.05
            if f > lim: bad.append(k)
    if bad: print('FAILING CLASSES:', bad)
    return errors

if __name__=='__main__':
    errs = score(sys.argv[1], sys.argv[2])
    if len(sys.argv)>3:
