        shown=0
        for kind,l,pu in errs:
            if want!='ALL' and kind!=want: continue
            if want=='ALL' and False: pass
            shown+=1
            if shown>n: break
            c = custs[l['customer_id']]
            print('---',kind, l['class'], repr(c['full_name']), 'dob=',c['dob'], c['type'], c['id_type'], c['id_number'])
