    ('sj', ['C']), ('tj', ['C']), ('dj', ['C']), ('cj', ['C']),
    ('ch', ['C', 'H', 'K']),
    ('kh', ['H', 'K']), ('gh', ['K']), ('ph', ['F']), ('th', ['T']),
