    ('dsch', ['C']), ('dzh', ['C']),
    ('sch', ['C']), ('tch', ['C']), ('tsh', ['C']), ('dzs', ['C']),
    ('sh', ['C']), ('zh', ['C']), ('cz', ['C']), ('sz', ['C']),
    ('sy', ['C', 'SY']), ('zs', ['C']),
    ('sj', ['C']), ('tj', ['C']), ('dj', ['C']), ('cj', ['C']),
    ('ch', ['C', 'H', 'K']),
    ('kh', ['H', 'K']), ('gh', ['K']), ('ph', ['F']), ('th', ['T']),
    ('ck', ['K']), ('qu', ['K']), ('ts', ['Z']), ('tz', ['Z']),
