    ('z', ['Z', 'C']),
    ('h', ['H']), ('k', ['K']),
    ('b', ['B']), ('p', ['B']),
    ('t', ['T']), ('d', ['D']),
    ('m', ['M']), ('n', ['N']), ('l', ['L']), ('r', ['R']),
