GRAPH_BY_FIRST = defaultdict(list)
for _g, _a in GRAPHEMES:
    GRAPH_BY_FIRST[_g[0]].append((_g, _a))

VCLASS = {'a': 'a', 'e': 'e', 'i': 'i', 'o': 'u', 'u': 'u',
          'y': 'i', 'j': 'i'}

CLUSTER_OVERRIDE = {
    'ee': set(['i']), 'aa': set(['a']), 'oo': set(['u']), 'ou': set(['u']),
    'oe': set(['u', 'i']), 'ue': set(['u']), 'ii': set(['i']),
    'uu': set(['u']), 'ei': set(['ai', 'i']), 'ie': set(['i', 'ia']),
}

_vcache = {}


def vowel_classes(cl):
    r = _vcache.get(cl)
    if r is not None:
        return r
    if cl in CLUSTER_OVERRIDE:
        _vcache[cl] = CLUSTER_OVERRIDE[cl]
        return _vcache[cl]
    seq = []
    for ch in cl:
        c = VCLASS.get(ch, 'a')
        if not seq or seq[-1] != c:
            seq.append(c)
    out = set()

    def rec(i, acc):
        if i == len(seq):
            s = ''
            for c in acc:
                if not s or s[-1] != c:
                    s += c
            if len(s) >= 3:
                out.add(s[0] + s[-1])
                out.add(s[:2])
                out.add(s[-2:])
            else:
                out.add(s)
            return
        if seq[i] == 'e':
            rec(i + 1, acc + ['a'])
            rec(i + 1, acc + ['i'])
        else:
            rec(i + 1, acc + [seq[i]])
