PRE_FOLD = {
    u'ß': 'ss', u'ẞ': 'ss',
    u'ø': 'o', u'Ø': 'o',
    u'đ': 'd', u'Đ': 'd',
    u'ł': 'l', u'Ł': 'l',
    u'æ': 'ae', u'Æ': 'ae',
    u'œ': 'oe', u'Œ': 'oe',
    u'ı': 'i', u'İ': 'i',
    u'ð': 'd', u'þ': 'th', u'Þ': 'th',
    u'ħ': 'h',
}

ARABIC_RANGE = (0x0600, 0x08FF)
CYRILLIC_RANGE = (0x0400, 0x04FF)


def script_of(text):
    for ch in text:
        o = ord(ch)
        if ARABIC_RANGE[0] <= o <= ARABIC_RANGE[1]:
            return 'arabic'
        if CYRILLIC_RANGE[0] <= o <= CYRILLIC_RANGE[1]:
            return 'cyrillic'
    return 'latin'


def fold_latin(s):
    """lower-case, strip diacritics, keep only a-z"""
    s = ''.join(PRE_FOLD.get(ch, ch) for ch in s)
