#!/usr/bin/env python3
"""Precision stress test: build look-alike decoys (same family name, a
different listed given name, and vice versa), render them in conventions the
dev sample does not use, and check the engine rejects them."""
import sys, json, re, random, collections
sys.path.insert(0, '/app')
import screen
sys.path.insert(0, '/tmp')
import stress as S

W = json.load(open('/app/watchlist.json'))
eng = screen.Engine(W)
random.seed(7)

# (given, family) shape of every individual entry, in cluster terms
pairs = set()
givens = collections.Counter()
families = collections.Counter()
ent_of = {}
for e in eng.entries:
    if e.type != 'individual':
        continue
    for variants in e.strong:
        u = variants[0]
        if len(u) != 2:
            continue
        a = frozenset(u[0].get_bases()), frozenset(u[1].get_bases())
        pairs.add((a[0], a[1]))
        pairs.add((a[1], a[0]))


def base(tokstr):
    return frozenset(screen.Unit(tokstr, [tokstr]).get_bases())


# collect latin (given, family) spellings per entry
samples = []
for e in eng.entries:
    if e.type != 'individual' or not e.strong:
        continue
    pn = e.raw['primary_name'] or ''
    if not re.search(r'[A-Za-z]', pn):
        continue
    u = e.strong[0][0]
    if len(u) != 2:
        continue
    samples.append((e, u[0].w, u[1].w))

given_pool = sorted(set(g for _, g, _ in samples))
family_pool = sorted(set(f for _, _, f in samples))

modes = sys.argv[1:] or ['plain', 'tr', 'id', 'sci', 'pl']
for mode in modes:
    tested = 0
    fps = []
    for e, g, f in samples:
        for which in (0, 1):
            for _ in range(6):
                if which == 0:
                    g2, f2 = random.choice(given_pool), f
                else:
                    g2, f2 = g, random.choice(family_pool)
                if (base(g2), base(f2)) in pairs:
                    continue
                if base(g2) == base(g) and which == 0:
                    continue
                if base(f2) == base(f) and which == 1:
                    continue
                break
            else:
                continue
            if (base(g2), base(f2)) in pairs:
                continue
            nm = '%s %s' % (g2.capitalize(), f2.capitalize())
            if mode != 'plain':
                nm = S.gen(nm, mode)
            tested += 1
            cust = {'customer_id': 'X', 'full_name': nm, 'dob': '',
                    'nationality': '', 'id_type': '', 'id_number': '',
                    'type': 'individual'}
            dec, uid = eng.decide(cust)
            if dec == 'MATCH':
                m = [z for z in W if z['uid'] == uid][0]
                fps.append((nm, g2, f2, m['primary_name'], uid))
    print('%-6s decoys %5d  false hits %4d  (%.4f)' %
          (mode, tested, len(fps), 1 - len(fps) / max(1, tested)))
    seen = set()
    for x in fps:
        k = (x[1], x[2], x[4])
        if k in seen:
            continue
        seen.add(k)
        if len(seen) > 25:
            break
        print('      %-34s  ->  %-34s %s' % (x[0][:34], (x[3] or '')[:34],
                                             x[4]))

