#!/usr/bin/env python3
"""Build a synthetic labelled batch that mirrors the dev class structure but
uses spelling conventions the dev sample does not contain, then score."""
import sys, json, re, random, unicodedata, collections, csv
sys.path.insert(0, '/app')
sys.path.insert(0, '/tmp')
import screen
import stress as S

W = json.load(open('/app/watchlist.json'))
eng = screen.Engine(W)
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 11)

LEGAL = ['LLC', 'L.L.C.', 'Limited Liability Company', 'Ltd', 'Limited',
         'S.A.', 'SA', 'Sociedad Anonima', 'GmbH', 'G.m.b.H.', 'JSC',
         'Joint Stock Company', 'AO', 'OAO', 'PJSC', 'Co.', 'Company',
         'FZE', 'FZ-LLC', 'Free Zone Establishment', 'Corp.', 'Corporation',
         'Inc', 'Incorporated', 'Anonim Sirketi']
VPREF = ['MV ', 'M/V ', 'MT ', 'M/T ', 'Vessel ', '', '', 'SS ']

PATRO = ['Ivanovich', 'Sergeyevich', 'Petrovich', 'Nikolaevich',
         'Aleksandrovich', 'Mikhailovich', 'Vladimirovich']
FATHERS = ['Ahmad', 'Khalid', 'Hisham', 'Yusuf', 'Majid', 'Abdul Aziz',
           'Karim', 'Tariq', 'Hamid', 'Abdul Rahman']
MODES = ['plain', 'plain', 'tr', 'id', 'sci', 'pl', 'de', 'fr', 'gulf']

DE = [('sh', 'sch'), ('ch', 'tsch'), ('v', 'w'), ('kh', 'ch'), ('j', 'dsch'),
      ('y', 'j'), ('ou', 'u'), ('ts', 'z')]
FR = [('sh', 'ch'), ('ch', 'tch'), ('ou', 'ou'), ('u', 'ou'), ('kh', 'kh'),
      ('v', 'v'), ('y', 'i'), ('ov', 'off')]
GULF = [('al-', 'al '), ('q', 'q'), ('ee', 'i'), ('i', 'ee')]


def conv(name, mode):
    if mode == 'plain':
        return name
    if mode in ('tr', 'id', 'sci', 'pl'):
        return S.gen(name, mode)
    rules = {'de': DE, 'fr': FR, 'gulf': GULF}[mode]
    out = []
    for tok in re.split(r'(\s+)', name):
        if not tok.strip():
            out.append(tok)
            continue
        low = unicodedata.normalize('NFKD', tok)
        low = ''.join(c for c in low if not unicodedata.combining(c)).lower()
        art = ''
        m = re.match(r'^(al|el)-', low)
        if m:
            art, low = m.group(0), low[len(m.group(0)):]
        for a, b in rules:
            low = low.replace(a, b)
        out.append(art + low.capitalize())
    return ''.join(out)


def sun(name):
    """gulf sun-letter assimilation of the article"""
    def rep(m):
        art, w = m.group(1), m.group(2)
        if w[0].lower() in 'tdrzsn':
            return 'a' + w[0].lower() + '-' + w
        return art + w
    return re.sub(r'\b(al-|el-)([A-Za-z])', lambda m: rep(m), name)


def person_names(e):
    pn = e['primary_name'] or ''
    if not re.search(r'[A-Za-z]', pn):
        pn = ''
    for a in e['aliases']:
        if a['strength'] == 'strong' and re.search(r'[A-Za-z]', a['name']):
            if not pn:
                pn = a['name']
    return pn


def structure(name):
    toks = name.split()
    r = random.random()
    if len(toks) >= 2:
        if r < 0.2:
            return toks[-1] + ', ' + ' '.join(toks[:-1])
        if r < 0.35:
            return toks[-1] + ' ' + ' '.join(toks[:-1])
        if r < 0.45:
            return toks[0] + ' ' + random.choice('ABCDEFGHJKLM') + '. ' + \
                ' '.join(toks[1:])
        if r < 0.55 and len(toks) == 2:
            if random.random() < .5:
                return toks[0] + ' ' + random.choice(PATRO) + ' ' + toks[1]
            return toks[0] + ' bin ' + random.choice(FATHERS) + ' ' + toks[1]
    return name


def drop_middle(name):
    toks = name.split()
    out, i = [], 0
    while i < len(toks):
        t = toks[i]
        if t.lower() in ('bin', 'ibn', 'ben'):
            i += 2
            if i - 1 < len(toks) and toks[i - 1].lower() in ('abdul', 'abd'):
                i += 1
            continue
        if re.search(r'(ovich|evich|ovna|evna)$', t, re.I):
            i += 1
            continue
        out.append(t)
        i += 1
    return ' '.join(out) if len(out) >= 2 else name


rows, labels = [], []
cid = 0


def add(name, dob, typ, idt, idn, exp, uid, cls):
    global cid
    cid += 1
    c = 'S%06d' % cid
    rows.append({'customer_id': c, 'full_name': name, 'dob': dob,
                 'nationality': 'XX', 'id_type': idt, 'id_number': idn,
                 'type': typ})
    labels.append({'customer_id': c, 'expected_decision': exp,
                   'expected_uid': uid, 'class': cls})


inds = [e for e in W if e['type'] == 'individual']
ents = [e for e in W if e['type'] == 'entity']
vess = [e for e in W if e['type'] == 'vessel']

# ---- true matches ---------------------------------------------------------
for e in inds:
    pn = person_names(e)
    if not pn:
        continue
    mode = random.choice(MODES)
    nm = conv(pn, mode)
    if random.random() < 0.35:
        nm = sun(nm)
    nm = structure(nm)
    if random.random() < 0.4:
        nm = drop_middle(nm)
    dob = e['dob']
    if dob and random.random() < 0.3:
        dob = dob[:random.choice([4, 7])]
    add(nm, dob, 'individual', '', '', 'MATCH', e['uid'], 'T_name_' + mode)

for e in ents:
    base = re.sub(r'(?i)\s*(%s)$' % '|'.join(re.escape(x) for x in LEGAL),
                  '', e['primary_name'] or '').strip()
    if not base:
        continue
    nm = base + ' ' + random.choice(LEGAL)
    if random.random() < 0.2:
        nm = 'The ' + nm
    if random.random() < 0.2:
        nm = nm.upper()
    add(nm, '', 'entity', '', '', 'MATCH', e['uid'], 'T_entity')

for e in vess:
    nm = random.choice(VPREF) + (e['primary_name'] or '')
    add(nm, '', 'vessel', '', '', 'MATCH', e['uid'], 'T_vessel')

# ---- identifier matches ---------------------------------------------------
for e in W:
    if not e['ids'] or random.random() > 0.35:
        continue
    i = e['ids'][0]
    add('Unrelated Person' if e['type'] == 'individual' else 'Unknown Co',
        '', e['type'], i['type'], i['number'], 'MATCH', e['uid'], 'T_id')

# ---- decoys ---------------------------------------------------------------
pairs = set()
for e in eng.entries:
    if e.type != 'individual':
        continue
    for v in e.strong:
        u = v[0]
        if len(u) == 2:
            a = frozenset(u[0].get_bases()), frozenset(u[1].get_bases())
            pairs.add((a[0], a[1]))
            pairs.add((a[1], a[0]))


def bs(t):
    return frozenset(screen.Unit(t, [t]).get_bases())


givens, families = [], []
for e in eng.entries:
    if e.type != 'individual' or not e.strong:
        continue
    u = e.strong[0][0]
    if len(u) == 2:
        givens.append(u[0].w)
        families.append(u[1].w)

for e in inds:
    pn = person_names(e)
    if not pn or not e['dob']:
        continue
    if random.random() < 0.5:
        mode = random.choice(MODES)
        nm = structure(conv(pn, mode))
        y = int(e['dob'][:4])
        d = '%04d%s' % (y + random.choice([-3, -2, 2, 3, 7]), e['dob'][4:])
        add(nm, d, 'individual', '', '', 'NO_MATCH', '', 'D_dob')
        if len(e['dob']) == 10:
            add(nm, '%04d' % (y + 4), 'individual', '', '', 'NO_MATCH', '',
                'D_dob_partial')

for e in eng.entries:
    if e.type != 'individual' or not e.strong:
        continue
    u = e.strong[0][0]
    if len(u) != 2:
        continue
    for which in (0, 1):
        for _ in range(8):
            if which == 0:
                g2, f2 = random.choice(givens), u[1].w
            else:
                g2, f2 = u[0].w, random.choice(families)
            if (bs(g2), bs(f2)) in pairs:
                continue
            break
        else:
            continue
        if (bs(g2), bs(f2)) in pairs:
            continue
        mode = random.choice(MODES)
        nm = structure(conv('%s %s' % (g2.capitalize(), f2.capitalize()),
                            mode))
        add(nm, '', 'individual', '', '', 'NO_MATCH', '',
            'D_near_' + ('given' if which == 0 else 'family'))

EWORDS = ['Trading', 'Shipping', 'Metals', 'Pharma', 'Energy', 'Logistics',
          'Minerals', 'Steel', 'Aviation', 'Chemicals', 'Petroleum',
          'Technologies', 'Industries', 'Holdings', 'Maritime']
for e in ents:
    base = re.sub(r'(?i)\s*(%s)$' % '|'.join(re.escape(x) for x in LEGAL),
                  '', e['primary_name'] or '').strip()
    toks = base.split()
    if len(toks) < 2:
        continue
    t2 = list(toks)
    t2[-1] = random.choice(EWORDS)
    if ' '.join(t2).lower() == base.lower():
        continue
    nm = ' '.join(t2) + ' ' + random.choice(LEGAL)
    exp = 'NO_MATCH'
    uid = ''
    for o in ents:
        ob = re.sub(r'(?i)\s*(%s)$' % '|'.join(re.escape(x) for x in LEGAL),
                    '', o['primary_name'] or '').strip()
        if ob.lower() == ' '.join(t2).lower():
            exp, uid = 'MATCH', o['uid']
            break
    add(nm, '', 'entity', '', '', exp, uid, 'D_entity')

for e in vess:
    nm = (e['primary_name'] or '') + ' ' + random.choice(
        ['Star', 'One', 'II', 'Spirit', 'Trader'])
    if any((o['primary_name'] or '').lower() == nm.lower() for o in vess):
        continue
    add(random.choice(VPREF) + nm, '', 'vessel', '', '', 'NO_MATCH', '',
        'D_vessel')

# ---- weak aliases ---------------------------------------------------------
for e in inds:
    wk = [a['name'] for a in e['aliases'] if a['strength'] == 'weak']
    if not wk:
        continue
    if random.random() < 0.5 and len(e['dob'] or '') == 10:
        add(wk[0], e['dob'], 'individual', '', '', 'MATCH', e['uid'],
            'T_weak_alias')
    elif random.random() < 0.3:
        add(wk[0], '', 'individual', '', '', 'NO_MATCH', '', 'D_weak_alone')

# ---- unlisted identifiers -------------------------------------------------
for e in inds[:300]:
    pn = person_names(e)
    if not pn:
        continue
    add(structure(conv(pn, random.choice(MODES))), e['dob'], 'individual',
        'passport', 'ZZ%08d' % random.randint(0, 99999999), 'MATCH',
        e['uid'], 'T_id_unlisted')

with open('/tmp/sim_cust.csv', 'w', newline='') as fh:
    w = csv.DictWriter(fh, ['customer_id', 'full_name', 'dob', 'nationality',
                            'id_type', 'id_number', 'type'])
    w.writeheader()
    w.writerows(rows)
with open('/tmp/sim_lab.csv', 'w', newline='') as fh:
    w = csv.DictWriter(fh, ['customer_id', 'expected_decision',
                            'expected_uid', 'class'])
    w.writeheader()
    w.writerows(labels)
print('wrote %d rows' % len(rows))

