# Used only to decide *which* base name an unseen spelling renders.  It keeps
# the readings that are genuinely ambiguous across languages (c, g, ch, kh,
# j) but not the ones that would let one name be read as another (s as sh,
# z as zh).
RESOLVE_OVERRIDE = {
    's': ['S'], 'z': ['Z'], 'sc': ['SK'],
}


def _graph_syms(w, mode=None):
    """-> list of alternative-symbol lists for a latin word."""
    syms = []
    i = 0
    n = len(w)
    def glide_is_vowel(k):
        """is w[k] ('y' or 'j') part of a vowel cluster?"""
        if k == 0:
            return False
        prev_v = w[k - 1] in VOWELS
        next_v = k + 1 < n and w[k + 1] in VOWELS
        if prev_v and next_v:
            return False            # intervocalic -> consonant (Khadija)
        return True

    def glide_also_consonant(k):
        """consonant + glide + vowel is read both ways"""
        return (0 < k < n - 1 and w[k] in 'yj' and
                w[k - 1] not in VOWELS and w[k + 1] in VOWELS)

    while i < n:
        ch = w[i]
        isv = ch in VOWELS or (ch in 'yj' and glide_is_vowel(i))
        if isv:
            j = i
            while j < n and (w[j] in VOWELS or
                             (w[j] in 'yj' and glide_is_vowel(j))):
                j += 1
            if glide_also_consonant(i):
                syms.append(['C', 'Y', ''] if ch == 'j' else ['Y', ''])
                cl = vowel_classes(w[i:j]) | vowel_classes(w[i + 1:j])
            else:
                cl = vowel_classes(w[i:j])
            syms.append(sorted(cl))
            i = j
            continue
        hit = None
        for g, alts in GRAPH_BY_FIRST.get(ch, ()):
            if w.startswith(g, i):
                hit = (g, alts)
                break
        if hit is None:
            i += 1
            continue
        g, alts = hit
        if g == 'c':
            nxt = w[i + 1] if i + 1 < n else ''
            if nxt in 'eiy':
                alts = ['K', 'S', 'Z', 'C']
            else:
                alts = ['K', 'Z', 'C']
        if mode == 'core':
            alts = CORE_OVERRIDE.get(g, alts)
            if g == 'w' and i + 1 < n and w[i + 1] in VOWELS:
                alts = ['F', 'u']
            elif i + len(g) == n and g in ('t', 'd'):
                alts = ['T', 'D']
        elif mode == 'resolve':
            alts = RESOLVE_OVERRIDE.get(g, alts)
            if g == 'w' and i + 1 < n and w[i + 1] in VOWELS:
                alts = ['F', 'u']
            elif i + len(g) == n and g in ('t', 'd'):
                alts = ['T', 'D']
            elif i + len(g) == n and g in ('b', 'p'):
                alts = ['B', 'P']
        elif g == 's':
            prev_v = i > 0 and w[i - 1] in VOWELS
            next_v = i + 1 < n and w[i + 1] in VOWELS
            if (i == 0 and next_v) or (prev_v and next_v):
                alts = ['S', 'C', 'Z']
        elif g == 'w' and i + 1 < n and w[i + 1] in VOWELS:
            alts = ['F', 'u']
        elif i + len(g) == n and g in ('t', 'd'):
            alts = ['T', 'D']          # final devoicing (Ahmet / Ahmad)
        elif i + len(g) == n and g in ('b', 'p'):
            alts = ['B', 'P']          # final devoicing (Zeynep / Zainab)
        syms.append(alts)
        i += len(g)
    return syms


def _collapse(k):
    out = []
    for ch in k:
        if not out or out[-1] != ch:
            out.append(ch)
    return ''.join(out)


